pub struct Token {
    pub kind: TokenKind,
    span: Span,
}
impl Token {
    pub fn as_parse_tree<'a>(&self) -> ParseTree<'a> {
        ParseTree::Token(*self)
    }
    pub fn span(&self) -> Span {
        self.span
    }
}
fn token_kind(terminal_id: ids::TerminalId) -> TokenKind {
    match terminal_id {
        // ","
        ids::TerminalId(0) => TokenKind::T0,
        // ";"
        ids::TerminalId(1) => TokenKind::T1,
        // "b"
        ids::TerminalId(2) => TokenKind::T2,
        // "c"
        ids::TerminalId(3) => TokenKind::T3,
        // "a"
        ids::TerminalId(4) => TokenKind::T4,
        // "if"
        ids::TerminalId(5) => TokenKind::T5,
        // "IF"
        ids::TerminalId(6) => TokenKind::T6,
        // "x"
        ids::TerminalId(7) => TokenKind::T7,
        // "y"
        ids::TerminalId(8) => TokenKind::T8,
        _ => unreachable!("Unknown TerminalId: {:?}", terminal_id),
    }
}
pub struct GeneratedNamesParseTreeBuilder<'a> {
    pub arena: &'a arena::Arena,
}
impl<'a> GeneratedNamesParseTreeBuilder<'a> {
    pub fn new(tree_arena: &'a arena::Arena) -> Self {
        Self { arena: tree_arena }
    }
    fn ambiguity_node(
        &self,
        parent: ids::NonterminalId,
        alternatives: &'a [ParseTree<'a>],
    ) -> ParseTree<'a> {
        match parent {
            grammar::S => ParseTree::S(self.arena.alloc(S::Amb(alternatives))),
            grammar::FIELDS => ParseTree::Fields(self.arena.alloc(Fields::Amb(alternatives))),
            grammar::BOX => ParseTree::Box(self.arena.alloc(Box::Amb(alternatives))),
            grammar::BOXES => ParseTree::Boxes(self.arena.alloc(Boxes::Amb(alternatives))),
            grammar::A => ParseTree::A(self.arena.alloc(A::Amb(alternatives))),
            grammar::ACCESSORS => {
                ParseTree::Accessors(self.arena.alloc(Accessors::Amb(alternatives)))
            }
            grammar::B => ParseTree::B(self.arena.alloc(B::Amb(alternatives))),
            grammar::C => ParseTree::C(self.arena.alloc(C::Amb(alternatives))),
            grammar::PLUS_0 => ParseTree::Plus0(self.arena.alloc(Plus0::Amb(alternatives))),
            grammar::PLUS_1 => ParseTree::Plus1(self.arena.alloc(Plus1::Amb(alternatives))),
            grammar::STAR_0 => ParseTree::Star0(self.arena.alloc(Star0::Amb(alternatives))),
            grammar::ALT_0 => ParseTree::Alt0(self.arena.alloc(Alt0::Amb(alternatives))),
            grammar::ALT_1 => ParseTree::Alt1(self.arena.alloc(Alt1::Amb(alternatives))),
            grammar::ALT_2 => ParseTree::Alt2(self.arena.alloc(Alt2::Amb(alternatives))),
            grammar::START_S => self.start_ambiguity_node(grammar::S, alternatives),
            grammar::START_FIELDS => self.start_ambiguity_node(grammar::FIELDS, alternatives),
            grammar::START_BOX => self.start_ambiguity_node(grammar::BOX, alternatives),
            grammar::START_BOXES => self.start_ambiguity_node(grammar::BOXES, alternatives),
            grammar::START_A => self.start_ambiguity_node(grammar::A, alternatives),
            grammar::START_ACCESSORS => self.start_ambiguity_node(grammar::ACCESSORS, alternatives),
            grammar::START_B => self.start_ambiguity_node(grammar::B, alternatives),
            grammar::START_C => self.start_ambiguity_node(grammar::C, alternatives),
            _ => unreachable!("nonterminal cannot be ambiguous"),
        }
    }
    fn start_ambiguity_node(
        &self,
        inner: ids::NonterminalId,
        alternatives: &'a [ParseTree<'a>],
    ) -> ParseTree<'a> {
        let first = alternatives[0].unwrap_start();
        let inner_alternatives = self
            .arena
            .alloc_slice(alternatives.iter().map(|a| a.unwrap_start().node));
        ParseTree::Start(self.arena.alloc(Start {
            before: first.before,
            node: self.ambiguity_node(inner, inner_alternatives),
            after: first.after,
            span: first.span,
        }))
    }
}
impl<'a> parse_tree::ParseTreeBuilder<ParseTree<'a>> for GeneratedNamesParseTreeBuilder<'a> {
    fn new_nonterminal_node(
        &self,
        nonterminal_node: &sppf::NonterminalNode,
        children: &[ParseTree<'a>],
    ) -> ParseTree<'a> {
        let span = nonterminal_node.span;
        match nonterminal_node.return_slot {
            // S = Fields Accessors
            SlotId(2) => {
                let &[accessors, fields] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::S(self.arena.alloc(S::Alt0 {
                    fields: fields.unwrap_fields(),
                    accessors: accessors.unwrap_accessors(),
                    span,
                }))
            }
            // Fields = Box+ Boxes ("," A)* ";" ("," A)*
            SlotId(8) => {
                let &[star_0_4, lit_3, star_0_2, boxes_1, boxes_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Fields(self.arena.alloc(Fields::Alt0 {
                    boxes_0: boxes_0.unwrap_plus_0(),
                    boxes_1: boxes_1.unwrap_boxes(),
                    star_0_2: star_0_2.unwrap_star_0(),
                    lit_3: lit_3.unwrap_token(),
                    star_0_4: star_0_4.unwrap_star_0(),
                    span,
                }))
            }
            // Box = "b"
            SlotId(10) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Box(self.arena.alloc(Box::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span,
                }))
            }
            // Boxes = "c"
            SlotId(12) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Boxes(self.arena.alloc(Boxes::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span,
                }))
            }
            // A = "a"
            SlotId(14) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::A(self.arena.alloc(A::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span,
                }))
            }
            // Accessors = (A B | A C) ("if" | "IF") (Box+ Boxes | C)
            SlotId(18) => {
                let &[alt_2, alt_1, alt_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Accessors(self.arena.alloc(Accessors::Alt0 {
                    alt_0: alt_0.unwrap_alt_0(),
                    alt_1: alt_1.unwrap_alt_1(),
                    alt_2: alt_2.unwrap_alt_2(),
                    span,
                }))
            }
            // B = "x"
            SlotId(20) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::B(self.arena.alloc(B::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span,
                }))
            }
            // C = "y"
            SlotId(22) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::C(self.arena.alloc(C::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span,
                }))
            }
            // Plus_0 = Box+ Box
            SlotId(25) => {
                let &[box_1, boxes_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus0(self.arena.alloc(Plus0::Alt0 {
                    boxes_0: boxes_0.unwrap_plus_0(),
                    box_1: box_1.unwrap_box(),
                    span,
                }))
            }
            // Plus_0 = Box
            SlotId(27) => {
                let &[r#box] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus0(self.arena.alloc(Plus0::Alt1 {
                    r#box: r#box.unwrap_box(),
                    span,
                }))
            }
            // Plus_1 = ("," A)+ "," A
            SlotId(31) => {
                let &[a, lit_1, plus_1] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus1(self.arena.alloc(Plus1::Alt0 {
                    plus_1: plus_1.unwrap_plus_1(),
                    lit_1: lit_1.unwrap_token(),
                    a: a.unwrap_a(),
                    span,
                }))
            }
            // Plus_1 = "," A
            SlotId(34) => {
                let &[a, lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus1(self.arena.alloc(Plus1::Alt1 {
                    lit_0: lit_0.unwrap_token(),
                    a: a.unwrap_a(),
                    span,
                }))
            }
            // Star_0 = ("," A)+
            SlotId(36) => {
                let &[plus_1] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star0(self.arena.alloc(Star0::Alt0 {
                    plus_1: plus_1.unwrap_plus_1(),
                    span,
                }))
            }
            // Star_0 =
            SlotId(37) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star0(self.arena.alloc(Star0::Alt1 { span }))
            }
            // Alt_0 = A B
            SlotId(40) => {
                let &[b, a] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt0(self.arena.alloc(Alt0::Alt0 {
                    a: a.unwrap_a(),
                    b: b.unwrap_b(),
                    span,
                }))
            }
            // Alt_0 = A C
            SlotId(43) => {
                let &[c, a] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt0(self.arena.alloc(Alt0::Alt1 {
                    a: a.unwrap_a(),
                    c: c.unwrap_c(),
                    span,
                }))
            }
            // Alt_1 = "if"
            SlotId(45) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt1(self.arena.alloc(Alt1::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span,
                }))
            }
            // Alt_1 = "IF"
            SlotId(47) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt1(self.arena.alloc(Alt1::Alt1 {
                    lit_0: lit_0.unwrap_token(),
                    span,
                }))
            }
            // Alt_2 = Box+ Boxes
            SlotId(50) => {
                let &[boxes_1, boxes_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt2(self.arena.alloc(Alt2::Alt0 {
                    boxes_0: boxes_0.unwrap_plus_0(),
                    boxes_1: boxes_1.unwrap_boxes(),
                    span,
                }))
            }
            // Alt_2 = C
            SlotId(52) => {
                let &[c] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt2(self.arena.alloc(Alt2::Alt1 {
                    c: c.unwrap_c(),
                    span,
                }))
            }
            // The start nonterminals without layout
            SlotId(54) | SlotId(56) | SlotId(58) | SlotId(60) | SlotId(62) | SlotId(64)
            | SlotId(66) | SlotId(68) => {
                let &[node] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Start(self.arena.alloc(Start {
                    before: None,
                    node,
                    after: None,
                    span,
                }))
            }
            _ => unreachable!(),
        }
    }
    fn new_token(&self, terminal_node: &sppf::TerminalNode) -> ParseTree<'a> {
        ParseTree::Token(Token {
            kind: token_kind(terminal_node.terminal_id),
            span: terminal_node.span,
        })
    }
    fn new_ambiguity_node(
        &self,
        parent: ids::NonterminalId,
        alternatives: Vec<ParseTree<'a>>,
    ) -> ParseTree<'a> {
        self.ambiguity_node(parent, self.arena.alloc_slice(alternatives))
    }
}
// The parse tree of a finished parse, from the nonterminal node that spans the input.
pub fn create_parse_tree<'a>(
    root_id: ids::SPPFNodeId,
    parser: &parser::GeneratedNamesParser,
    builder: &GeneratedNamesParseTreeBuilder<'a>,
) -> ParseTree<'a> {
    let iguana_runtime::sppf::SPPFNode::Nonterminal(root) =
        iguana_runtime::parser::Parser::sppf_node(parser, root_id)
    else {
        panic!("the SPPF root is not a nonterminal node")
    };
    match root.nonterminal_id {
        grammar::S => ParseTree::S(visit_sppf(root_id, parser, builder).unwrap_s()),
        grammar::FIELDS => ParseTree::Fields(visit_sppf(root_id, parser, builder).unwrap_fields()),
        grammar::BOX => ParseTree::Box(visit_sppf(root_id, parser, builder).unwrap_box()),
        grammar::BOXES => ParseTree::Boxes(visit_sppf(root_id, parser, builder).unwrap_boxes()),
        grammar::A => ParseTree::A(visit_sppf(root_id, parser, builder).unwrap_a()),
        grammar::ACCESSORS => {
            ParseTree::Accessors(visit_sppf(root_id, parser, builder).unwrap_accessors())
        }
        grammar::B => ParseTree::B(visit_sppf(root_id, parser, builder).unwrap_b()),
        grammar::C => ParseTree::C(visit_sppf(root_id, parser, builder).unwrap_c()),
        grammar::PLUS_0 => ParseTree::Plus0(visit_sppf(root_id, parser, builder).unwrap_plus_0()),
        grammar::PLUS_1 => ParseTree::Plus1(visit_sppf(root_id, parser, builder).unwrap_plus_1()),
        grammar::STAR_0 => ParseTree::Star0(visit_sppf(root_id, parser, builder).unwrap_star_0()),
        grammar::ALT_0 => ParseTree::Alt0(visit_sppf(root_id, parser, builder).unwrap_alt_0()),
        grammar::ALT_1 => ParseTree::Alt1(visit_sppf(root_id, parser, builder).unwrap_alt_1()),
        grammar::ALT_2 => ParseTree::Alt2(visit_sppf(root_id, parser, builder).unwrap_alt_2()),
        grammar::START_S
        | grammar::START_FIELDS
        | grammar::START_BOX
        | grammar::START_BOXES
        | grammar::START_A
        | grammar::START_ACCESSORS
        | grammar::START_B
        | grammar::START_C => ParseTree::Start(visit_sppf(root_id, parser, builder).unwrap_start()),
        _ => panic!(),
    }
}
impl<'a> parse_tree::ParseTreeNode for ParseTree<'a> {
    fn child(&self, index: usize) -> Option<Self> {
        ParseTree::child(self, index)
    }
    fn child_count(&self) -> usize {
        ParseTree::child_count(self)
    }
    fn display_name(&self) -> &'static str {
        ParseTree::display_name(self)
    }
    fn span(&self) -> Span {
        ParseTree::span(self)
    }
    fn kind(&self) -> parse_tree::NodeKind {
        if self.is_amb() {
            parse_tree::NodeKind::Amb
        } else if matches!(self, ParseTree::Token(_)) {
            parse_tree::NodeKind::Token
        } else {
            parse_tree::NodeKind::Nonterminal
        }
    }
    fn node_id(&self) -> Option<usize> {
        ParseTree::node_id(self)
    }
    fn nonterminal_id(&self) -> Option<ids::NonterminalId> {
        ParseTree::nonterminal_id(self)
    }
    fn origin(&self) -> Option<Origin> {
        ParseTree::origin(self)
    }
}
